"""RouterAgent — generated by G2C (e2a_inherited); hooks implemented by hand (E2A v1.2 contract).

Classifies a natural-language request into one intent. It decides nothing else: the
intent only selects which specialist step of the workflow runs, and the entitlement
stage checks the caller's role for that specialist before it runs.
"""
import json
import logging

from e2a import BaseAgent

from ..services.llm import ROUTER

INTENTS = ("PLACE_ORDER", "ORDER_STATUS", "PAYMENT_EXCEPTIONS", "POLICY_QUESTION", "UNSUPPORTED")


class RouterAgent(BaseAgent):
    """Inherits the public entry point and every NFR from BaseAgent. Each hook receives
    only the parameters it declares (state, ctx, messages, ...); the model is reached
    only through config['llm_service']."""
    agent_name = 'RouterAgent'

    def _build_messages(self, state, ctx) -> list:
        return [{'role': 'system', 'content': f'You are the {ROUTER}. Classify the request into exactly one '
                                              f'intent of {", ".join(INTENTS)}; answer as JSON {{"intent": ...}}.'},
                {'role': 'user', 'content': str(state.get('query', ''))}]

    def _apply_policy(self, state, ctx) -> None:
        approved = ctx.setting('approved_agents', [])        # kept from the G2C skeleton; [] = no list set
        if approved and self.agent_name not in approved:
            raise PermissionError(f'{self.agent_name} is not an approved agent')

    def _evaluate_output(self, response, state, ctx) -> float:
        text = (response or {}).get('text', '') if isinstance(response, dict) else str(response or '')
        try:
            intent = json.loads(text).get('intent')
        except (ValueError, AttributeError):
            return 0.0
        if intent not in INTENTS:
            return 0.0
        state['intent'] = intent
        return 1.0

    def _fallback(self, state, ctx):
        state['intent'] = 'UNSUPPORTED'
        return {'text': json.dumps({'intent': 'UNSUPPORTED'}), 'degraded': True}

    def _handle_error(self, error, state, ctx):
        logging.error(f'[{self.agent_name}] {error}')
        state.setdefault('errors', []).append(str(error))
        state['intent'] = 'UNSUPPORTED'
